INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("新年を迎え、新たに始まる一日を\nおみくじで占ってみませんか？\n良い運勢であるほど、\n沢山のプレゼントが貰えますよ♪", "カリン", 1, 60000, 190804, 0, 1, 0, 1, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　あらゆる運気が最大を示しています！　　　今なら「伝説の吸血鬼」をも従え、世界征服も夢じゃありません！", "", 0, 60000, 0, 1, 1, 0, 2, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　やること全てが最高潮！　やばいですね☆　ラッキーアイテムはおにぎり！　お腹一杯で幸せが続くでしょう！", "", 0, 60000, 0, 1, 1, 0, 3, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　その高い運気はまさにショーグンの如く！　その溢れる威光は人々を惹きつけ、皆の人気者間違いなしです！", "", 0, 60000, 0, 1, 2, 0, 4, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　運気がどんどん高まっています！　　　　　何をやっても、最大効率で素晴らしい結果になりますよ♪", "", 0, 60000, 0, 2, 1, 0, 5, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　なにをやっても上手くいって大活躍！　　　そんな素敵なあなたを見て、後ろから誰かが……クスクス♪", "", 0, 60000, 0, 2, 1, 0, 6, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　運気が高く、何かに挑戦すると良い結果に！隠れた才能が引き出されそう！　目指せヒデサ……ではなく秀才！", "", 0, 60000, 0, 2, 2, 0, 7, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　商売運が上がってきています！　　　　　　ラッキーアイテムはたいやき！　和菓子パワーで売上アップです！", "", 0, 60000, 0, 3, 1, 0, 8, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　旅行運がぐんぐんと上昇中♪　　　　　　　もしかしたら、あの「マホマホ王国」にだって行けるかも♪", "", 0, 60000, 0, 3, 1, 0, 9, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　仕事運が急上昇中です！　　　　　　　　　きっと「煉獄に舞う一陣の疾風」の如き活躍ができますよ！", "", 0, 60000, 0, 3, 1, 0, 10, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　チャンスを待つと良い結果に！　　　　　　ラッキーアイテムのプリンを食べて、運を呼び込みましょう！", "", 0, 60000, 0, 3, 1, 0, 11, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　運気が着々と上昇中！　　　　　　　　　　精霊の加護を受けたかの如く、色々な事がうまくいきますよ♪", "", 0, 60000, 0, 3, 2, 0, 12, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　早朝に幸運の兆しあり！　　　　　　　　　もしかしたら、優しいお姉ちゃんが起こしにきてくれますよ♪", "", 0, 60000, 0, 4, 1, 0, 13, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　運気上昇中ですが、上がるまでが要注意！　ラッキーアニマルは熊！　本当の家族のように守ってくれるかも♪", "", 0, 60000, 0, 4, 1, 0, 14, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　外に出てゆっくり過ごすと運気が上昇！　　ラッキースポットは牧場。面白い出会いがありそうです♪", "", 0, 60000, 0, 4, 1, 0, 15, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　運気は高いけども、ハプニングには注意！　出かけた先で、「ふしんしゃ」扱いされてしまうかも……", "", 0, 60000, 0, 4, 1, 0, 16, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　根を詰めずにリラックスすると運気向上！　ラッキーパーソンはアイドル。歌があなたを幸せにしてくれます♪", "", 0, 60000, 0, 4, 2, 0, 17, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("おみくじの結果はどうでしたか？\n新たに始まる一日が、あなたに\nとって良い日になりますように\nまた明日も遊びに来て下さいね♪", "カリン", 2, 60000, 190804, 0, 0, 0, 18, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("おみくじは楽しんで頂けましたか？\nあなたの新たなる年が\n素晴らしいものになるよう、\n心からお祈りいたします", "カリン", 3, 60000, 190804, 0, 0, 7, 19, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("キミと出会ってもう\n1年もたつんだね！\nう～ん、いつも\n寝てばっかりだから、", "ハツネ", 1, 80001, 101201, 0, 0, 1, 20, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("少しでも\n寝る時間を減らして\nキミと一緒にいる\n時間増やしたいなぁ♪", "ハツネ", 2, 80001, 101201, 0, 0, 1, 21, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あなたと知り合ってから\nもう1年…\n時がたつのは\n早いですね", "シオリ", 1, 80001, 103801, 0, 0, 1, 22, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("来年も、\n一緒にいられたら…\nうれしいな", "シオリ", 2, 80001, 103801, 0, 0, 1, 23, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あなたと一緒にいるようになって、\nもう1年ですか…", "キョウカ", 1, 80001, 103601, 0, 0, 2, 24, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("最初の頃よりも、頼もしく\nなりましたね。私はどうですか？\n成長していますか？", "キョウカ", 2, 80001, 103601, 0, 0, 2, 25, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("おにいちゃんとあってから、\n1年たったよ～！", "ミミ", 1, 80001, 102001, 0, 0, 2, 26, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ミミね、おにいちゃんと\nいっぱい遊べてたのしかったな～♪\nこれからもずっと\nいっしょにいてね～！", "ミミ", 2, 80001, 102001, 0, 0, 2, 27, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("にいちゃんがミソギのイタズラに\n引っかかり続けてもう1年かぁ", "ミソギ", 1, 80001, 100401, 0, 0, 2, 28, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("…これからもいっぱいミソギと\n遊んでね、にいちゃん！", "ミソギ", 2, 80001, 100401, 0, 0, 2, 29, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("もう王子はんと会うてから\n1年ぐらいたつそうどすえ\n早いもんやなあ", "マホ", 1, 80001, 101001, 0, 0, 3, 30, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("このままやと、\nうちもあっという間に\n干からびてしまいそうどすえ\nなーんてな。うふふ", "マホ", 2, 80001, 101001, 0, 0, 3, 31, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("お主と会って早1年じゃな\nこれからも存分に尽くすがよい", "イリヤ", 1, 80001, 104401, 0, 0, 3, 32, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("わらわもたまには、お主の献身に\n報いてやらぬでもない♪", "イリヤ", 2, 80001, 104401, 0, 0, 3, 33, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("もう、キミと出会って結構な時間が\nたつさ～。でも、私たちの旅は\nまだまだ始まったばかりさ～！", "カオリ", 1, 80001, 101701, 0, 0, 3, 34, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("これからも、どうぞよろしく\nお願いするさ～！", "カオリ", 2, 80001, 101701, 0, 0, 3, 35, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あんたと出会ってからもうそんなに\nたつのね～", "サレン", 1, 80001, 102801, 0, 0, 4, 36, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あっという間だったって感じるほど\n楽しかったわ！\nこれからも一緒に頑張りましょ！", "サレン", 2, 80001, 102801, 0, 0, 4, 37, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("出会ってから1年間、ずっと\nご迷惑をかけっぱなしで、\nすみません…", "スズメ", 1, 80001, 102501, 0, 0, 4, 38, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("これからはもっと頑張りますから\n見ていてくださいね\nできれば…\n今までよりも、私の近くで♪", "スズメ", 2, 80001, 102501, 0, 0, 4, 39, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("振り返れば、今までいろんなことが\nあったにゃあ…", "タマキ", 1, 80001, 104601, 0, 0, 5, 40, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("これからも、二人でたくさんの\n思い出をがっぽり作っていく\nにゃー！", "タマキ", 2, 80001, 104601, 0, 0, 5, 41, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("キミとの師弟関係も、\nもう1年なのね…\nでもキミに教えることは、", "ミフユ", 1, 80001, 104801, 0, 0, 5, 42, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("まだまだいっぱいあるわ\nこれからも、\nしっかりついて来てね！", "ミフユ", 2, 80001, 104801, 0, 0, 5, 43, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あなたさまと出会ってもう1年…", "アキノ", 1, 80001, 103201, 0, 0, 6, 44, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("光陰矢のごとし、とはまさに\nこのことですわ。…思い出は決して\nお金では買えませんわね", "アキノ", 2, 80001, 103201, 0, 0, 6, 45, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ダメな私を1年間も見捨てないで\nくれて、本当にありがとう", "ユカリ", 1, 80001, 103401, 0, 0, 6, 46, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("情けないところいっぱいみせるかも\nしれないけど、これからも一緒に\nいてくれると、うれしいな", "ユカリ", 2, 80001, 103401, 0, 0, 6, 47, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("オマエと出会ってもう1年か\nまさかこのワタシの結婚相手に\nなろうとはな…", "クリスティーナ", 1, 80001, 107101, 0, 0, 7, 48, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ともかくこれからも\n愉しませてくれよ☆", "クリスティーナ", 2, 80001, 107101, 0, 0, 7, 49, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("君と出会ってからもう1年か。\n以前と比べて私の表情もいくらか\n柔らかくなった気がするんだが、\nどうだろう？", "ジュン", 1, 80001, 104701, 0, 0, 7, 50, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("見えないから分からないって？\nそれもそうだな…", "ジュン", 2, 80001, 104701, 0, 0, 7, 51, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("もう1年たったみたいだね\nあなたをからかってばかりだった\nけど、楽しかった♪", "トモ", 1, 80001, 103701, 0, 0, 8, 52, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("これからもよろしくね！", "トモ", 2, 80001, 103701, 0, 0, 8, 53, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("出会って、もう1年たっちゃった\nんスね。なんだか意外ッス", "マツリ", 1, 80001, 100501, 0, 0, 8, 54, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("毎日楽しくて、あっという間に過ぎ\nちゃったみたいなんスよね\nこれからも一緒に悪と戦うッス！", "マツリ", 2, 80001, 100501, 0, 0, 8, 55, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("オマエと会って1年なの！\n全然成仏もできなかったし、", "ミヤコ", 1, 80001, 100701, 0, 0, 9, 56, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("生き返りもしなかったけど、\nすごく楽しかったの～♪\nオマエとプリンがあれば、\nミヤコはハッピーなの～♪", "ミヤコ", 2, 80001, 100701, 0, 0, 9, 57, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あなたと出会って1年なんですね\nでも、私の占いでは、私とあなたは", "シノブ", 1, 80001, 103101, 0, 0, 9, 58, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("来年も再来年も一緒にいるようです\nふふ、よろしくお願いしますね", "シノブ", 2, 80001, 103101, 0, 0, 9, 59, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("貴様が閃光のシグルドとして覚醒し\nもう1年か…。これからも我らの\n長き戦いに終わりはないが、", "アンナ", 1, 80001, 100901, 0, 0, 10, 60, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("それでも貴様となら…\n添い遂げる覚悟はできているぞ！", "アンナ", 2, 80001, 100901, 0, 0, 10, 61, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("君と出会ってもう1年だって！\n早いねー！", "ナナカ", 1, 80001, 101301, 0, 0, 10, 62, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("これからも最強のバディタッグで\n大活躍だー！\n頼りにしてるよ、相棒！", "ナナカ", 2, 80001, 101301, 0, 0, 10, 63, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("1年たつのって、あっという間ね\nまだまだ君の知らない部分が\nたくさんあるし…", "ミツキ", 1, 80001, 105101, 0, 0, 11, 64, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("これからも、いろんなところを\n調べさせてね？", "ミツキ", 2, 80001, 105101, 0, 0, 11, 65, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("お前さんと出会ってもう1年か\n助太刀するつもりが", "ルカ", 1, 80001, 105601, 0, 0, 11, 66, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("逆に助けられたりもしたね\nこれからもよろしく頼むよ！", "ルカ", 2, 80001, 105601, 0, 0, 11, 67, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("早いものですわね、あなた様と\nお会いして、もう1年…", "エリコ", 1, 80001, 102701, 0, 0, 11, 68, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あなた様といると、時があっと\nいう間に過ぎてしまいます\n時間を止める研究をしなくては\nいけませんね…", "エリコ", 2, 80001, 102701, 0, 0, 11, 69, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("お兄ちゃんと会ってから、もう、\n1年なんだね。私、少しは\nお姉ちゃんっぽくなったかな？", "アヤネ", 1, 80001, 102301, 0, 0, 12, 70, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あ、ぷうきちもお兄ちゃんっぽく\nなったよね？", "アヤネ", 2, 80001, 102301, 0, 0, 12, 71, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あなたと出会って、\nもう1年がたったんですね…\nこれからもそばにいて、", "チカ", 1, 80001, 104201, 0, 0, 12, 72, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("私のことを見守ってください\nできることなら、ずっと…", "チカ", 2, 80001, 104201, 0, 0, 12, 73, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("お兄ちゃんと出会って1年かぁ\n私、相変わらずダメダメで…", "クルミ", 1, 80001, 102101, 0, 0, 12, 74, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("で、でもこれからもずっと…\n一緒にいたいなぁ…", "クルミ", 2, 80001, 102101, 0, 0, 12, 75, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("再会してちょうど1年だね\nお祝いにごちそう作ってきたよ～♪\n特製ケーキと、お寿司と、", "シズル", 1, 80001, 104901, 0, 0, 13, 76, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ハンバーグと、カレーと、\nシチューと、あ、隠しきれない隠し\n味は、お姉ちゃんの愛情だよ！", "シズル", 2, 80001, 104901, 0, 0, 13, 77, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("お兄ちゃんと再会して、もう1年\nなんですね。\n会えなかった時を思うと、", "リノ", 1, 80001, 101101, 0, 0, 13, 78, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("信じられないくらい幸せな1年\nでした！もう絶対、私から離れ\nないでくださいね♪", "リノ", 2, 80001, 101101, 0, 0, 13, 79, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("騎士クンと出会ってから今まで、\nいろんなことがあったよね\n楽しいこと、ドキドキしたこと…", "ユイ", 1, 80001, 100201, 0, 0, 14, 80, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("そんな日々をこれからも、\nず、ずっと一緒に…\n過ごしていきたいな…！", "ユイ", 2, 80001, 100201, 0, 0, 14, 81, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("騎士くんと出会って、まだ1年しか\nたってないんだ！？", "ヒヨリ", 1, 80001, 100101, 0, 0, 14, 82, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("なんかもうずっと一緒にいる気が\nするなぁ…えへへ。これからの\n1年もまたよろしくねっ！\n騎士くん！", "ヒヨリ", 2, 80001, 100101, 0, 0, 14, 83, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("初めてキミに出会って1年…\n随分見違えたね私もキミも、\n更に強くなっていく…", "レイ", 1, 80001, 100301, 0, 0, 14, 84, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("キミに背中を預けられる日が、\n早くきますように", "レイ", 2, 80001, 100301, 0, 0, 14, 85, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("1年もわたしのことを、忘れない\nでいてくれて、ありがとうござい\nます！", "ペコリーヌ", 1, 80001, 105801, 0, 0, 15, 86, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("これからもずっと、覚えていて\nくださいね！", "ペコリーヌ", 2, 80001, 105801, 0, 0, 15, 87, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("こうして1年も、主さまのおそばに\n置いていただけて、とても光栄\nです。どうかこれからも、", "コッコロ", 1, 80001, 105901, 0, 0, 15, 88, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("末永く主さまをお世話させて\nください。わたくしは、ずっと\n主さまのガイド役でいたいのです", "コッコロ", 2, 80001, 105901, 0, 0, 15, 89, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("1年か、まっさかこんなに長い\n付き合いになるなんてね～\nでも…わりと楽しい1年だったかも", "キャル", 1, 80001, 106001, 0, 0, 15, 90, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("だから、もうしばらくあんたに\n付き合ってやるわよ喜びなさい！", "キャル", 2, 80001, 106001, 0, 0, 15, 91, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("新しい年のはじめに、\nおみくじはいかがでしょうか？\nよい運勢であるほど、\n沢山プレゼントが貰えますよ♪", "スズメ", 1, 60001, 112101, 0, 1, 0, 92, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　あらゆる運気が最大を示しています！　　　今なら「伝説の吸血鬼」をも従え、世界征服も夢じゃありません！", "", 0, 60001, 0, 1, 1, 0, 93, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　やること全てが最高潮！　やばいですね☆　ラッキーアイテムはおにぎり！　お腹一杯で幸せが続くでしょう！", "", 0, 60001, 0, 1, 1, 0, 94, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　最強の運勢でどんなドジも跳ね除けます！　大切な人と一緒に、最高の一日になること間違いなし！", "", 0, 60001, 0, 1, 1, 0, 95, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　どんな挑戦も上手くいく、最高の運勢です！理想の自分に変身できる絶好の機会！　新しい一歩を踏み出そう！", "", 0, 60001, 0, 1, 1, 0, 96, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　その高い運気はまさにショーグンの如く！　その溢れる威光は人々を惹きつけ、皆の人気者間違いなしです！", "", 0, 60001, 0, 1, 2, 0, 97, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　運気がどんどん高まっています！　　　　　何をやっても、最大効率で素晴らしい結果になりますよ♪", "", 0, 60001, 0, 2, 1, 0, 98, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　なにをやっても上手くいって大活躍！　　　そんな素敵なあなたを見て、後ろから誰かが……クスクス♪", "", 0, 60001, 0, 2, 1, 0, 99, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　ラッキーワードは「ちぇる～ん♪」　　　　出会う人みんなに言ってあげると、ハッピーになれますよ！", "", 0, 60001, 0, 2, 1, 0, 100, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　運勢はバッチリで無敵状態！　　　　　　　龍眼で全てを見通して、思い通りの一日を過ごしましょう！", "", 0, 60001, 0, 2, 1, 0, 101, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　運気が高く、何かに挑戦すると良い結果に！隠れた才能が引き出されそう！　目指せヒデサ……ではなく秀才！", "", 0, 60001, 0, 2, 2, 0, 102, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　商売運が上がってきています！　　　　　　ラッキーアイテムはたいやき！　和菓子パワーで売上アップです！", "", 0, 60001, 0, 3, 1, 0, 103, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　旅行運がぐんぐんと上昇中♪　　　　　　　もしかしたら、あの「マホマホ王国」にだって行けるかも♪", "", 0, 60001, 0, 3, 1, 0, 104, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　仕事運が急上昇中です！　　　　　　　　　きっと「煉獄に舞う一陣の疾風」の如き活躍ができますよ！", "", 0, 60001, 0, 3, 1, 0, 105, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　チャンスを待つと良い結果に！　　　　　　ラッキーアイテムのプリンを食べて、運を呼び込みましょう！", "", 0, 60001, 0, 3, 1, 0, 106, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　お出かけした先で良縁に恵まれそうです！　ダウナー系あざとい女子が、あま～い飴をくれるかも？", "", 0, 60001, 0, 3, 1, 0, 107, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　大抵のことはゴリ押しでなんとかできます！ラッキープレイスはゲーセン。パンチングマシンでストレス発散！", "", 0, 60001, 0, 3, 1, 0, 108, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　運気が着々と上昇中！　　　　　　　　　　精霊の加護を受けたかの如く、色々な事がうまくいきますよ♪", "", 0, 60001, 0, 3, 2, 0, 109, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　早朝に幸運の兆しあり！　　　　　　　　　もしかしたら、優しいお姉ちゃんが起こしにきてくれますよ♪", "", 0, 60001, 0, 4, 1, 0, 110, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　運気上昇中ですが、上がるまでが要注意！　ラッキーアニマルは熊！　本当の家族のように守ってくれるかも♪", "", 0, 60001, 0, 4, 1, 0, 111, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　外に出てゆっくり過ごすと運気が上昇！　　ラッキースポットは牧場。面白い出会いがありそうです♪", "", 0, 60001, 0, 4, 1, 0, 112, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　運気は高いけども、ハプニングには注意！　出かけた先で、「ふしんしゃ」扱いされてしまうかも……", "", 0, 60001, 0, 4, 1, 0, 113, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　同腹一心の友だちが見つかるかも！　　　　キーワードは「ユニちゃんズ」、記憶に刻みましょう！", "", 0, 60001, 0, 4, 1, 0, 114, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　思わぬ相手と仲良くなれるかも？　　　　　うっかり毒舌をもらしてしまわないように要注意です！", "", 0, 60001, 0, 4, 1, 0, 115, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　根を詰めずにリラックスすると運気向上！　ラッキーパーソンはアイドル。歌があなたを幸せにしてくれます♪", "", 0, 60001, 0, 4, 2, 0, 116, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("おみくじの結果はいかがでしたか？\n新たに始まる一日が、\nあなたにとってよい日になりますように\n明日もお待ちしていますね♪", "スズメ", 2, 60001, 112101, 0, 0, 0, 117, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("おみくじ、楽しんで頂けましたか？\nあなたの新しい年が\n素晴らしいものになるよう、\n心からお祈りしますね", "スズメ", 3, 60001, 112101, 0, 0, 7, 118, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ヒューヒュー♪\nドンドンパフパフー♪", "ペコリーヌ", 1, 80003, 105801, 0, 0, 1, 119, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ひゅーひゅー\nどんどんぱふぱふー\nでございます", "コッコロ", 1, 80003, 105901, 0, 0, 1, 120, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("さぁ、キャルさまもご一緒に\nどんどんぱふぱふいたしましょう", "コッコロ", 2, 80003, 105901, 0, 0, 1, 121, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("え？　ちょっと\nいきなりなにっ？", "キャル", 1, 80003, 106001, 0, 0, 1, 122, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ドンドンパフパフってなんなの？\nあたしにも分かるように\nちゃんと説明しなさいっての！", "キャル", 2, 80003, 106001, 0, 0, 1, 123, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("実はですねキャルちゃん！\nもうすぐわたしたちにとっての\n大切な節目──", "ペコリーヌ", 2, 80003, 105801, 0, 0, 1, 124, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("『プリンセスコネクト！\nRe:Dive』\n2.5周年なんですよ！\nやばいですね☆", "ペコリーヌ", 3, 80003, 105801, 0, 0, 1, 125, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ですからその日に向けて\n今から気分を盛り上げているのです", "コッコロ", 3, 80003, 105901, 0, 0, 1, 126, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ああ、そういえば\nそんな時期だっけ\nって言っても、もう少し先じゃない\n気が早いんじゃないの？", "キャル", 3, 80003, 106001, 0, 0, 1, 127, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("いいえ、キャルさま\nこういったお祝いは準備から\n楽しむものでございます\nそうですよね、ペコリーヌさま", "コッコロ", 4, 80003, 105901, 0, 0, 1, 128, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("その通りです♪　というわけで！\nカウントダウンの始まりですよ！\nみんなで一緒に2.5周年に向けて\n盛り上がっていきましょー☆", "ペコリーヌ", 4, 80003, 105801, 0, 0, 1, 129, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ド、ドンドンパフパフ～\nって何言わせんのよ！\nまったくもう、浮かれちゃってさ", "キャル", 4, 80003, 106001, 0, 0, 1, 130, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ふふ。キャルさまもワクワクして\nおいでのようですね\nそれでは主さま。大切な記念日まで\nどうぞご期待くださいませ", "コッコロ", 5, 80003, 105901, 0, 0, 1, 131, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("記念日を盛り上げるったって\n一体どうしたらいいのよ？\nあたし、そういうの\n苦手なんだけど…", "キャル", 5, 80003, 106001, 0, 0, 2, 132, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あら、キャルさん\nどうかなさいましたか？\n何かお困りのようですけど", "カリン", 1, 80003, 190801, 0, 0, 2, 133, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("げっ…カリンじゃない\nなんでもないわよ！", "キャル", 6, 80003, 106001, 0, 0, 2, 134, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("そうなのですか？\nキャルさんのことですからてっきり\n2.5周年をどう盛り上げたら\nいいか悩んでいるのかと…", "カリン", 2, 80003, 190801, 0, 0, 2, 135, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("分かってんじゃないのよ！？\nいっ、いや、違うけどね！\nあたしは別にそんなことで\n悩んでないわよっ？", "キャル", 7, 80003, 106001, 0, 0, 2, 136, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ふふっ…\nこういう時は、真心を込めて\n気持ちをそのまま口にしたら\nいいのではないでしょうか？", "カリン", 3, 80003, 190801, 0, 0, 2, 137, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("気持ちを、ねぇ\nそれが一番難しいんじゃない…\nそもそも、あたしは記念日とか\n別にどうだっていいし", "キャル", 8, 80003, 106001, 0, 0, 2, 138, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("…まあ、ペコリーヌもコロ助も\nやけに楽しそうだったから…\nこういうお祭り騒ぎみたいなのも\nたまにはいいかな、とは思うけど", "キャル", 9, 80003, 106001, 0, 0, 2, 139, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("なるほどなるほど～\nキャルさんは【美食殿】で祝う\n2.5周年を心から楽しみに\nしている、ということですね！", "カリン", 4, 80003, 190801, 0, 0, 2, 140, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("はぁ！？\nどこ聞いたらそうなるのよ！\nあたしは別に楽しみになんか…！", "キャル", 10, 80003, 106001, 0, 0, 2, 141, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("キャルさんの心からの想い\nみなさんにも伝わったでしょうか？\n私も2.5周年が楽しみです！\n以上、カリンがお伝えしました！", "カリン", 5, 80003, 190801, 0, 0, 2, 142, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("心からの想いって何なのよ！？\n勝手に人の言葉を\n捻じ曲げんじゃないわよ！\nこのくそ眼鏡ーーーっ！", "キャル", 11, 80003, 106001, 0, 0, 2, 143, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ペコリーヌさま、もうすぐ\n記念日でございますね\nこういった節目というのは\n感慨深いものでございます", "コッコロ", 6, 80003, 105901, 0, 0, 3, 144, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("色んな思い出が蘇ってきますね！\n楽しい出来事が\nいっぱいありました♪", "ペコリーヌ", 5, 80003, 105801, 0, 0, 3, 145, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("はい、そうでございますね\n主さまも【美食殿】の活動の他にも\nいろんなご経験をされたと\n聞いておりますよ", "コッコロ", 7, 80003, 105901, 0, 0, 3, 146, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("たしか…ランドソルで話題沸騰と\nなっていた、魔法少女なるものに\nお会いになられたとか", "コッコロ", 8, 80003, 105901, 0, 0, 3, 147, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("魔法少女って、あの美味しくって\n栄養たっぷりの大ヒット商品\n『魔法少女ソーセージ』の箱に\n描いてある女の子のことですか！？", "ペコリーヌ", 6, 80003, 105801, 0, 0, 3, 148, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あのソーセージ\n美味しいんですよね～♪\nわたしもたっくさん食べてますよ！", "ペコリーヌ", 7, 80003, 105801, 0, 0, 3, 149, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あとは、牧場に素敵な温泉が\n出来たとか…", "コッコロ", 9, 80003, 105901, 0, 0, 3, 150, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("牧場ですか！？　温泉につかって\nチーズもオツですね～♪　考えた\nだけでよだれが出ちゃいそうです！\nやばいですね☆", "ペコリーヌ", 8, 80003, 105801, 0, 0, 3, 151, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ペコリーヌさま\n言ってるそばからよだれが…\n今お拭きしますね。ふき、ふき", "コッコロ", 10, 80003, 105901, 0, 0, 3, 152, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("えへへ、ありがとうございます\nコッコロちゃん！", "ペコリーヌ", 9, 80003, 105801, 0, 0, 3, 153, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("それにしても、主さまは\n【美食殿】の一員として様々な\n美食と出会われていたのですね\nわたくし、感服いたしました", "コッコロ", 11, 80003, 105901, 0, 0, 3, 154, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("これからもたくさん冒険をして\nめいっぱい美食を\n味わい尽くしましょうね！", "ペコリーヌ", 10, 80003, 105801, 0, 0, 3, 155, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("2.5周年カウントダウン♪\nキャルちゃんキャルちゃん！\nわくわくしますね☆", "ペコリーヌ", 11, 80003, 105801, 0, 0, 4, 156, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あぁもう、うるさいわね～\nまだまだ先でしょ？\nちょっとは落ち着きなさいよ", "キャル", 12, 80003, 106001, 0, 0, 4, 157, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("キャルちゃんだって最近\nソワソワしてるじゃないですか～\nさっきもご機嫌そうに鼻歌とか\n歌ってましたよね？", "ペコリーヌ", 12, 80003, 105801, 0, 0, 4, 158, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("なっ…！　き、聞いてたの！？\nじゃない、歌ってないわよ！？\nあんたいい加減なこと言うと\nぶっ殺すわよ！？", "キャル", 13, 80003, 106001, 0, 0, 4, 159, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("えっへへ～♪\nわたしは最近のキャルちゃんが\nもっともっと大好きですよ♪\nすごく積極的になりましたよね！", "ペコリーヌ", 13, 80003, 105801, 0, 0, 4, 160, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("…積極的？\nなんの話よ？", "キャル", 14, 80003, 106001, 0, 0, 4, 161, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("またまた～♪\nアイドルを目指そうとしたこと\n忘れちゃったんですか？", "ペコリーヌ", 14, 80003, 105801, 0, 0, 4, 162, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ムーサの町で\nきゃるきゃる～ん☆　って！", "ペコリーヌ", 15, 80003, 105801, 0, 0, 4, 163, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あっ…！？　ちちち違うわよっ！\nあれは操られてただけで\nあたしはアイドルなんか\n目指してないっての！！", "キャル", 15, 80003, 106001, 0, 0, 4, 164, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("本当に本当ですか？\nわたし、キャルちゃんとっても\n乗り気だなって\n思ってたんですけど～", "ペコリーヌ", 16, 80003, 105801, 0, 0, 4, 165, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("まぁ、悪くはなかったけど…って\nだ、だから目指してないって\n言ってるでしょ！！\nなんてこと思い出させんのよ！？", "キャル", 16, 80003, 106001, 0, 0, 4, 166, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ああ…ダメだわ…\nもう殺すしかない…\n2.5周年が来る前に\n記憶ごと消し去ってやるー！", "キャル", 17, 80003, 106001, 0, 0, 4, 167, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("2.5周年まであと10日…\nふ～ん？\n案外早いもんね？", "キャル", 18, 80003, 106001, 0, 0, 5, 168, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("そうでございますね…\nその日のためにやるべきことは\nまだまだございます\n気を引き締めねばなりません…！", "コッコロ", 12, 80003, 105901, 0, 0, 5, 169, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("やる気十分ねコロ助…\nそんな気負ってるとしんどいわよ？\nお気楽にやりましょ？", "キャル", 19, 80003, 106001, 0, 0, 5, 170, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("キャルさま…\nありがとうございます\nキャルさまは本当に\n優しいおかたです", "コッコロ", 13, 80003, 105901, 0, 0, 5, 171, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("な、なにわけの分かんないこと\n言ってんのよ…\nあたしは優しくなんかないっての", "キャル", 20, 80003, 106001, 0, 0, 5, 172, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("そんなことはございません\n…あの、実はわたくし\nキャルさまに\nひとつお願いがございまして", "コッコロ", 14, 80003, 105901, 0, 0, 5, 173, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("お願い？　珍しいわね\nコロ助がそんなこと言うなんて\n…まあ、あたしに出来ることなら\n別にいいけど", "キャル", 21, 80003, 106001, 0, 0, 5, 174, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ありがとうございます\n実は記念日へ向けて\n『かくし芸』というものを\n用意してみようかと思いまして", "コッコロ", 15, 80003, 105901, 0, 0, 5, 175, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("かくし芸？", "キャル", 22, 80003, 106001, 0, 0, 5, 176, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("はい。きゃるきゃる～ん☆　を\n参考に、ころころ～ん☆　という\nご挨拶を考えてみたのですが\nポーズがうまくいかなくて…", "コッコロ", 16, 80003, 105901, 0, 0, 5, 177, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("～～！！　ちょっと褒められて\nいい気になって損したわ！！\nふざけんなふざけんな\nふ～ざ～け～ん～な～っ！！", "キャル", 23, 80003, 106001, 0, 0, 5, 178, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あと９日！　もうすぐですよ♪\nえへへ、楽しみで楽しみで\nごはんが進みますね☆", "ペコリーヌ", 17, 80003, 105801, 0, 0, 6, 179, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ごはんが進みますね☆\nじゃなーい！\nいくらなんでも食べ過ぎよ！\n記念日、迎えられなくなるわよ！？", "キャル", 24, 80003, 106001, 0, 0, 6, 180, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("大丈夫ですよキャルさま\n食事はわたくしたちの\n歩んできた道そのもの\nなのですから", "コッコロ", 17, 80003, 105901, 0, 0, 6, 181, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("さっすがコッコロちゃん\nいいことを言いますね！\nそう、わたしたち\n【美食殿】の活動目的は─", "ペコリーヌ", 18, 80003, 105801, 0, 0, 6, 182, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("─みんなで楽しく食事をすること\nでしょ？\nあれだけ食べ歩いてきたんだから\n分かってるわよ", "キャル", 25, 80003, 106001, 0, 0, 6, 183, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("はい…そうでございますね♪\nそれにしてもわたくしたち\n本当にいろいろなものを\n食べ歩いてきましたね…", "コッコロ", 18, 80003, 105901, 0, 0, 6, 184, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("そうね…ほんっとうにね…\n毒まみれのニセドラゴンとか\n恐竜…は逃げられちゃったっけ\nあとワニゴ…ワニの魔物とかね", "キャル", 26, 80003, 106001, 0, 0, 6, 185, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("そして、とうとう本物の\nドラゴンまで相手に\nしちゃったのよね、あたしたちって", "キャル", 27, 80003, 106001, 0, 0, 6, 186, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("信じられない強さだったわね\nあのドラゴン…やっぱり\n作戦はしっかり立てていかないと\nダメよね", "キャル", 28, 80003, 106001, 0, 0, 6, 187, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("えへへ…☆\nキャルちゃんが色んなことを\n覚えていてくれて\nうれしいです♪", "ペコリーヌ", 19, 80003, 105801, 0, 0, 6, 188, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("わたくしも鮮明に覚えておりますよ\n主さまもきっと…♪", "コッコロ", 19, 80003, 105901, 0, 0, 6, 189, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あったり前でしょ！\n忘れないわよ、あんな滅茶苦茶な\nものばかり食べさせられて！\n…忘れられるわけ、ないじゃない", "キャル", 29, 80003, 106001, 0, 0, 6, 190, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ねえちょっと、ちょっと待って！？\nカリンから、2.5周年記念の\n生放送に出演してほしいって\n言われたんだけど！", "キャル", 30, 80003, 106001, 0, 0, 7, 191, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("なんでそういう大事なことを\n急に言うわけ！？\nそんなの聞いてないわよ～！？", "キャル", 31, 80003, 106001, 0, 0, 7, 192, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("いっぱい人に見られちゃうのよね？\nなんであたしがそんなこと…", "キャル", 32, 80003, 106001, 0, 0, 7, 193, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あー\nあー\n…声、これで大丈夫かしら？", "キャル", 33, 80003, 106001, 0, 0, 7, 194, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("聞き取りにくいかもしれないわね…\nもうちょっと明るい方がいいかも\nえっと…こんな感じ？", "キャル", 34, 80003, 106001, 0, 0, 7, 195, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("オイッスー☆", "キャル", 35, 80003, 106001, 0, 0, 7, 196, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("……\nいや、ないわ\nいつもどおりが一番ね、うん", "キャル", 36, 80003, 106001, 0, 0, 7, 197, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("もう、記念の生放送なんて\n超責任重大なやつじゃない…\nもしなにか失敗とかしたら…", "キャル", 37, 80003, 106001, 0, 0, 7, 198, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ど、どど、どうしよう！？\n緊張してきちゃった…！！", "キャル", 38, 80003, 106001, 0, 0, 7, 199, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("主さま、わたくし\nペコリーヌさまとキャルさまと共に\n2.5周年を祝う生放送に\n出演する大役を仰せつかりました", "コッコロ", 20, 80003, 105901, 0, 0, 8, 200, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("多くの方々に\n『プリンセスコネクト！\nRe:Dive』の魅力をお伝えする\n重要な役割でございます", "コッコロ", 21, 80003, 105901, 0, 0, 8, 201, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("わたくし、全身全霊をもって\n生放送に取り組みたいと\n思っております", "コッコロ", 22, 80003, 105901, 0, 0, 8, 202, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ですが、もしかしたら\nセリフを噛んでしまったり\n段取りを間違えてしまったり\nするかもしれません…", "コッコロ", 23, 80003, 105901, 0, 0, 8, 203, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("そのようなことがないよう\n練習はしっかりしておかなくては\nまずはこちらから…", "コッコロ", 24, 80003, 105901, 0, 0, 8, 204, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("オイッスー☆", "コッコロ", 25, 80003, 105901, 0, 0, 8, 205, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("先ほどキャルさまが練習されて\nいるのをお見かけしたので\nわたくしもと思いまして…\nいかがでしょうか？", "コッコロ", 26, 80003, 105901, 0, 0, 8, 206, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("良い感じ、ですか？\n…ふふ、ありがとうございます\n主さまのあたたかいお言葉があれば\nわたくしは百人力でございます", "コッコロ", 27, 80003, 105901, 0, 0, 8, 207, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("この大役を無事に成し遂げ\n主さまに素敵な2.5周年を\n迎えていただけるよう…\nわたくし、尽力いたしますね", "コッコロ", 28, 80003, 105901, 0, 0, 8, 208, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("オイッスー☆", "ペコリーヌ", 20, 80003, 105801, 0, 0, 9, 209, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("…う～ん、今のはちょっと\n違う感じがしますね\n堅苦しかったかもしれません", "ペコリーヌ", 21, 80003, 105801, 0, 0, 9, 210, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あと６日で2.5周年ですか…", "ペコリーヌ", 22, 80003, 105801, 0, 0, 9, 211, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("この年月がオイッスーの\n歴史なんだと思うと\nじ～んとしちゃいます！\nやばいですね☆", "ペコリーヌ", 23, 80003, 105801, 0, 0, 9, 212, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("生放送で最高のオイッスー☆　を\nみなさんにお届けするために\n頑張らないと！\nそれじゃあもう一度…", "ペコリーヌ", 24, 80003, 105801, 0, 0, 9, 213, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("オイッスー☆", "ペコリーヌ", 25, 80003, 105801, 0, 0, 9, 214, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("…うう～ん、どうしてでしょう\nまだ何かが違う気がします…\nもしかしたら\nおなかが空きすぎてるとか？", "ペコリーヌ", 26, 80003, 105801, 0, 0, 9, 215, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今さっき食べたばっかりですけど\nおなかが減っては\n良いオイッスー☆　は\n出せませんよね！", "ペコリーヌ", 27, 80003, 105801, 0, 0, 9, 216, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("そうと決まれば、コッコロちゃんと\nキャルちゃんを誘って\nごはんにしましょう！\n善は急げです！", "ペコリーヌ", 28, 80003, 105801, 0, 0, 9, 217, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あ、二人が丁度いいところに！\nオイッス～☆　…ああ！！\n今の、今のですよ～♪", "ペコリーヌ", 29, 80003, 105801, 0, 0, 9, 218, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("なるほど、どんな時も\n自然体が一番ってことですね！\nこの調子で、生放送も\n頑張っちゃいます♪", "ペコリーヌ", 30, 80003, 105801, 0, 0, 9, 219, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("2.5周年まで残り５日ですが\nその前にもうすぐ生放送ですよ！\nコッコロちゃん\n準備の方はどうですか？", "ペコリーヌ", 31, 80003, 105801, 0, 0, 10, 220, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("はい。わたくし、しっかりと\n備えてまいりました\n万事抜かりはございません", "コッコロ", 29, 80003, 105901, 0, 0, 10, 221, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("おお～すごい自信を感じます…！\nいい生放送になりそうですね☆\n……あれ？　なんだかこの辺り\n揺れていませんか？", "ペコリーヌ", 32, 80003, 105801, 0, 0, 10, 222, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("…………", "キャル", 39, 80003, 106001, 0, 0, 10, 223, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("キャルさま？\nお風邪をひかれたんでしょうか\nひどい震えですが…", "コッコロ", 30, 80003, 105901, 0, 0, 10, 224, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("かかかか風邪じゃないわよ！\nここここれはただ\nななな生放送が楽しみ過ぎて\nワワワワクワクが止まらないだけ！", "キャル", 40, 80003, 106001, 0, 0, 10, 225, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("大丈夫ですかキャルちゃん！？\nそうだ、これを飲んでください！", "ペコリーヌ", 33, 80003, 105801, 0, 0, 10, 226, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("きき気がきくじゃない、ありがとっ\nごくっ、んく…ぶはぁっ！？\nちょっと何飲ませたの！？\n辛っ！　苦ぁ！？　甘ぁっ！？", "キャル", 41, 80003, 106001, 0, 0, 10, 227, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("これは魔物のエキスに薬草に\nその他色んなものを混ぜた\n特製の栄養ドリンクです！", "ペコリーヌ", 34, 80003, 105801, 0, 0, 10, 228, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("これを飲めば体ぽかぽかで\n元気いっぱいですよ♪", "ペコリーヌ", 35, 80003, 105801, 0, 0, 10, 229, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("このアホリーヌ！\n風邪じゃないって言ったでしょ！？\nどさくさに紛れて\nそんな恐ろしいもん飲ませんな～！", "キャル", 42, 80003, 106001, 0, 0, 10, 230, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("キャルさま\n震えが収まっておりますね\nよかったです…\nわたくし、心配いたしました", "コッコロ", 31, 80003, 105901, 0, 0, 10, 231, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("え？　ああ、ホントね…って\nだから風邪じゃないって\n言ってるのに…\nまあいいわこの際なんでも", "キャル", 43, 80003, 106001, 0, 0, 10, 232, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("えっへへ～♪　いつも通りの\nキャルちゃんに戻りましたし\n素敵な生放送が出来そうですね！\n今から楽しみです☆", "ペコリーヌ", 36, 80003, 105801, 0, 0, 10, 233, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ランドソルのみなさま、こんにちは\n生放送の会場設営を担当しています\n【ギルド管理協会】のカリンです", "カリン", 6, 80003, 190801, 0, 0, 11, 234, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("【美食殿】のみなさんは\nまもなく始まる生放送に向けて\n最後の調整のため\n席を外しています", "カリン", 7, 80003, 190801, 0, 0, 11, 235, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("頑張っている３人の\n邪魔をするわけには\nいきませんので、ご容赦ください", "カリン", 8, 80003, 190801, 0, 0, 11, 236, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ですので、本日は私から\n【美食殿】のみなさんの様子を\nお伝えさせていただこうと思います", "カリン", 9, 80003, 190801, 0, 0, 11, 237, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("まずはペコリーヌさんですが…\n何やら大量のおにぎりを\n食べているようです\nえっと…栄養は大事ですよね", "カリン", 10, 80003, 190801, 0, 0, 11, 238, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("次にコッコロさんですが\nこちらは発声練習をしています", "カリン", 11, 80003, 190801, 0, 0, 11, 239, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("一生懸命、小さなお口を開けて\n声を出す姿が応援したくなりますね", "カリン", 12, 80003, 190801, 0, 0, 11, 240, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("そしてキャルさんは…\nこれは…堂々としたものですね\n何もせず、ただ立ち尽くして…", "カリン", 13, 80003, 190801, 0, 0, 11, 241, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あれ？\nもしかして緊張で気を失って…？", "カリン", 14, 80003, 190801, 0, 0, 11, 242, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("…ええと\n【美食殿】のみなさんは\nやる気十分なようですね！", "カリン", 15, 80003, 190801, 0, 0, 11, 243, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("３人とも生放送を\nいいものにしようと\n全力で頑張ってくれていますので\nどうかご期待ください", "カリン", 16, 80003, 190801, 0, 0, 11, 244, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("それでは\nまた明日お会いしましょう♪", "カリン", 17, 80003, 190801, 0, 0, 11, 245, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("2.5周年まであと３日！\nそして生放送は明日！\nなんかいよいよって感じね…", "キャル", 44, 80003, 106001, 0, 0, 12, 246, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("３人でい～っぱい練習しましたし\nきっと大丈夫ですよ☆", "ペコリーヌ", 37, 80003, 105801, 0, 0, 12, 247, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ペコリーヌさまに\n大丈夫と言ってもらえると\nとても心強いですね", "コッコロ", 32, 80003, 105901, 0, 0, 12, 248, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("信じすぎちゃだめよコロ助\nこいつはなーんにも\n考えてないだけなんだから", "キャル", 45, 80003, 106001, 0, 0, 12, 249, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ひどいですよぉキャルちゃ～ん！", "ペコリーヌ", 38, 80003, 105801, 0, 0, 12, 250, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ふふ。お二人とも\n普段通りの様子で\n安心いたしました", "コッコロ", 33, 80003, 105901, 0, 0, 12, 251, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("はいっ☆\n生放送でもなんでも\n全力全開、わたしらしく\nぶつかっていくだけです！", "ペコリーヌ", 39, 80003, 105801, 0, 0, 12, 252, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("そうね。おめでたいことなんだし\nここまで来たんなら\n楽しめるだけ\n楽しむしかないわよね！", "キャル", 46, 80003, 106001, 0, 0, 12, 253, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("わたくしも、普段よりも心が\n熱くなっております\nこの胸の気持ちをお伝えできるよう\n精一杯努力いたします…！", "コッコロ", 34, 80003, 105901, 0, 0, 12, 254, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("それでは、いきましょう！\n明日の生放送、絶対に\n成功させましょうね☆", "ペコリーヌ", 40, 80003, 105801, 0, 0, 12, 255, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("えっと、最初のひと言は…あれ？\nキャルちゃん、わたし\n何て言うんでしたっけ？", "ペコリーヌ", 41, 80003, 105801, 0, 0, 13, 256, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("は！？\nなにいきなりど忘れしてるの！？\nっていうかあんた、台本は！？", "キャル", 47, 80003, 106001, 0, 0, 13, 257, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("忘れてきちゃいました☆", "ペコリーヌ", 42, 80003, 105801, 0, 0, 13, 258, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("忘れてきちゃいました☆\nで済ませられると思ってんの！？\nほら、あたし二冊持ってきたから\nこれ使いなさい！", "キャル", 48, 80003, 106001, 0, 0, 13, 259, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("マイクとは、こんな高い位置に\nあるものなのですね…！\n背伸びをすれば、何とか…\nう～ん、うぅ～ん…！", "コッコロ", 35, 80003, 105901, 0, 0, 13, 260, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あぁもう\n少し下げればいいでしょ！？\nこれくらいでいい？\nまったく、世話が焼けるわね…", "キャル", 49, 80003, 106001, 0, 0, 13, 261, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あれ？\nキャルちゃん、後ろ髪が\nはねちゃってますよ？", "ペコリーヌ", 43, 80003, 105801, 0, 0, 13, 262, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("え？　うそっ！？\nちゃんと確かめてきたのに！\nどこどこ！？", "キャル", 50, 80003, 106001, 0, 0, 13, 263, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("キャルさま、動かないで\nくださいまし。今くしで…\nはい、直りましたよ", "コッコロ", 36, 80003, 105901, 0, 0, 13, 264, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あ、ありがと…はぁ。生放送\n本番までもうすぐなのに\nこんなことしてる場合じゃ\nないわよね", "キャル", 51, 80003, 106001, 0, 0, 13, 265, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("はい、時間は残りわずかです\nですが、慌ただしく\n動き回るこの時間も\nなんだか楽しくて…♪", "コッコロ", 37, 80003, 105901, 0, 0, 13, 266, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("コロ助、あんた…って\nそうじゃなくて！\n胸にジンワリきてる\n暇なんかないでしょ…！？", "キャル", 52, 80003, 106001, 0, 0, 13, 267, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あはは♪\nキャルちゃんの動きが\nとっても面白いです♪\nやばいですね☆", "ペコリーヌ", 44, 80003, 105801, 0, 0, 13, 268, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ふふ\nきっと面白い生放送になると\nわたくし、確信しております", "コッコロ", 38, 80003, 105901, 0, 0, 13, 269, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("絶対絶対、間違いありません！\n見てくれるみなさんが\n笑顔になれる時間を\nお届けしましょう！", "ペコリーヌ", 45, 80003, 105801, 0, 0, 13, 270, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("そんなの当然でしょ！\n誰が見たって面白いって\n言ってもらえるように\nあれだけ準備したんだから！", "キャル", 53, 80003, 106001, 0, 0, 13, 271, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("それでは\n記念日直前生放送！\n楽しみにしててくださいね☆", "ペコリーヌ", 46, 80003, 105801, 0, 0, 13, 272, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("こんにちは\n【ギルド管理協会】のカリンです", "カリン", 18, 80003, 190801, 0, 0, 14, 273, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("昨日の生放送は\nいかがだったでしょうか？", "カリン", 19, 80003, 190801, 0, 0, 14, 274, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("たくさんの笑顔と喜びと\nそして驚きを受け取って\nいただけたのではないかと思います", "カリン", 20, 80003, 190801, 0, 0, 14, 275, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("そしていよいよ\n明日は2.5周年の当日\n待ちに待った記念日を\n迎えることとなります", "カリン", 21, 80003, 190801, 0, 0, 14, 276, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("【美食殿】のみなさんも\n張り切って様々な準備を\nされていますよ", "カリン", 22, 80003, 190801, 0, 0, 14, 277, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("【ギルド管理協会】も\n万全のサポート体制で\n協力してまいりたいと思います", "カリン", 23, 80003, 190801, 0, 0, 14, 278, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("…ふふ、本当に楽しみですね\n【ギルド管理協会】の職員として\nだけではなく、私個人としても…", "カリン", 24, 80003, 190801, 0, 0, 14, 279, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("この記念日を迎えられることが\n心から楽しみですし\n幸せを感じています", "カリン", 25, 80003, 190801, 0, 0, 14, 280, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("きっと【美食殿】のみなさんは\nそれ以上に心を弾ませて\nいることでしょう", "カリン", 26, 80003, 190801, 0, 0, 14, 281, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("それでは\n明日からの2.5周年を\nどうぞ、お楽しみに…♪", "カリン", 27, 80003, 190801, 0, 0, 14, 282, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("準備はいいですかっ？\n…いっきますよー！", "ペコリーヌ", 47, 80003, 105801, 0, 0, 15, 283, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("祝！", "キャル", 54, 80003, 106001, 0, 0, 15, 284, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("2.5周年！", "コッコロ", 39, 80003, 105901, 0, 0, 15, 285, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("おめでとうございま～す☆", "ペコリーヌ", 48, 80003, 105801, 0, 0, 15, 286, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("少し前まではまだまだ先じゃない\nとか言ってたけど\n本当にあっという間だったわね", "キャル", 55, 80003, 106001, 0, 0, 15, 287, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("光陰矢の如し…\nとはこのことでございますね\nでも、今日という日を無事に\n迎えることができて良かったです", "コッコロ", 40, 80003, 105901, 0, 0, 15, 288, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("コッコロちゃん！　キャルちゃん！\n落ち着くには\nまだ早いですよ！\n盛り上がるのはこれからです☆", "ペコリーヌ", 49, 80003, 105801, 0, 0, 15, 289, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ほんとあんたはいつも\n全力全開ねー\nでもそうね、記念日なんだし\nパーっといきましょ！", "キャル", 56, 80003, 106001, 0, 0, 15, 290, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ええ、わたくしも全力全開で\nまいります…！\n主さま、さあ\nどうぞ手を取ってくださいまし…♪", "コッコロ", 41, 80003, 105901, 0, 0, 15, 291, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あんたもコロ助も、浮かれて\n転ぶんじゃないわよ？\n…仕方ないから、あたしも\n手を繋いであげるわよ", "キャル", 57, 80003, 106001, 0, 0, 15, 292, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あー！　二人ともずるいです！\nわたしもっ、ギュー♪", "ペコリーヌ", 50, 80003, 105801, 0, 0, 15, 293, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ちょっ、ペコリーヌ！\nくっつき過ぎよ！", "キャル", 58, 80003, 106001, 0, 0, 15, 294, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("記念日だから\n平気平気♪\nやばいですね☆", "ペコリーヌ", 51, 80003, 105801, 0, 0, 15, 295, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("意味分かんないわよ！", "キャル", 59, 80003, 106001, 0, 0, 15, 296, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ふふ。このめでたき日に\n喜びがあふれておりますね\n主さまは…いかがでしょうか？", "コッコロ", 42, 80003, 105901, 0, 0, 15, 297, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("喜んでいただけているならば\nわたくしはとてもとても\n幸せでございます", "コッコロ", 43, 80003, 105901, 0, 0, 15, 298, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("さぁ、2.5周年を\n楽しみ尽くしますよ☆\nまだまだ食べたいものもありますし\nやりたいこともたくさんです！", "ペコリーヌ", 52, 80003, 105801, 0, 0, 15, 299, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("分かった、分かったから\n引っ張るんじゃないわよ！\n…そんな掴まなくても\nちゃんとついていくから", "キャル", 60, 80003, 106001, 0, 0, 15, 300, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ペコリーヌさま…キャルさま…\n主さま…共にまいりましょう\nどこまでも…！", "コッコロ", 44, 80003, 105901, 0, 0, 15, 301, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("はい！　それでは2.5周年\n食べつくしツアーへ！\nそして、その先の未来へ\n向かって出発しましょう！", "ペコリーヌ", 53, 80003, 105801, 0, 0, 15, 302, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("2.5周年\nありがとうございます！", "ペコリーヌ・コッコロ・キャル", 54, 80003, 105801, 0, 0, 15, 303, "105901,45,106001,61", 0, 1);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("新年を迎え、新たに始まる一日を\nおみくじで占ってみませんか？\n良い運勢であるほど、\n沢山のプレゼントが貰えますよ♪", "カリン", 1, 60002, 190804, 0, 1, 0, 304, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　どんな不可能も可能にできちゃう！　　　　仲間と食卓を囲めばさらに運気上昇よ！　ただし魔物料理以外！", "", 0, 60002, 0, 1, 1, 0, 305, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　やること全てが最高潮！　やばいですね☆　ラッキーアイテムはおにぎり！　お腹一杯で幸せが続くでしょう！", "", 0, 60002, 0, 1, 1, 0, 306, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　最強の運勢でどんなドジも跳ね除けます！　大切な人と一緒に、最高の一日になること間違いなし！", "", 0, 60002, 0, 1, 1, 0, 307, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　どんな挑戦も上手くいく、最高の運勢です！理想の自分に変身できる絶好の機会！　新しい一歩を踏み出そう！", "", 0, 60002, 0, 1, 1, 0, 308, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　やること全てが上手くいく最高の一日！　　あなたの活躍に先生もにっこりです。いい子いい子♪", "", 0, 60002, 0, 1, 2, 0, 309, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　お裁縫好きな女の子のお墨付きです！　　　お世話したがりの妹にめいっぱい愛されちゃうかも！？", "", 0, 60002, 0, 2, 1, 0, 310, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　ラッキーカラーは赤！　　　　　　　　　　湧き上がるアイデアの数々に、高笑いが止まりませんわ！", "", 0, 60002, 0, 2, 1, 0, 311, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　ラッキーワードは「ちぇる～ん♪」　　　　出会う人みんなに言ってあげると、ハッピーになれますよ！", "", 0, 60002, 0, 2, 1, 0, 312, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　運勢はバッチリで無敵状態！　　　　　　　龍眼で全てを見通して、思い通りの一日を過ごしましょう！", "", 0, 60002, 0, 2, 1, 0, 313, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　悩んでいたことが解決しそうです！　　　　たまには勉強も仕事も忘れて、心あたたまる家族と過ごしましょ！", "", 0, 60002, 0, 2, 2, 0, 314, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　家の中でゆっくり過ごすのがよさそう！　　ラッキーアイテムはゲームよ！　ベストスコアを更新できるかも？", "", 0, 60002, 0, 3, 1, 0, 315, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　上手くなりたいことに積極的に挑戦してみてサックス好きの妹が、手取り足取りサポートしてくれるかも～？", "", 0, 60002, 0, 3, 1, 0, 316, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　仕事運が急上昇中です！　　　　　　　　　きっと「煉獄に舞う一陣の疾風」の如き活躍ができますよ！", "", 0, 60002, 0, 3, 1, 0, 317, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　日頃の努力が報われます！　　　　　　　　親しい友人がいるなら報告してみて。一緒に喜んでくれるはずだ。", "", 0, 60002, 0, 3, 1, 0, 318, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　商売運が上がってきています！　　　　　　ラッキーアイテムはたい焼き！　和菓子パワーで売上アップです！", "", 0, 60002, 0, 3, 1, 0, 319, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　チャンスを待つと良い結果に！　　　　　　ラッキーアイテムのプリンを食べて、運を呼び込みましょう！", "", 0, 60002, 0, 3, 1, 0, 320, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　運気が着々と上昇中！　　　　　　　　　　精霊の加護を受けたかのごとく、色々な事がうまくいきますよ♪", "", 0, 60002, 0, 3, 2, 0, 321, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　まだ見ぬ危険が隠れているかも！　　　　　でも安心しろ！　提督が貴公を守ってくれるはずだぞ！", "", 0, 60002, 0, 4, 1, 0, 322, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　いろんな事件が起こる一日になりそう！　　状況をよく観察してみようじゃないか！　まさに探偵のごとくね！", "", 0, 60002, 0, 4, 1, 0, 323, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　気の向くままに過ごすのが幸せへの近道！　美味い魚を食べて猫を眺めて、自然体で過ごすのはどうだい？", "", 0, 60002, 0, 4, 1, 0, 324, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　運気は高いけども、ハプニングには注意！　出かけた先で、「ふしんしゃ」扱いされてしまうかも……", "", 0, 60002, 0, 4, 1, 0, 325, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　同腹一心の友だちが見つかるかも！　　　　キーワードは「ユニちゃんズ」、記憶に刻みましょう！", "", 0, 60002, 0, 4, 1, 0, 326, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　周りに流されず、マイペースな一日を！　　ただし寝すぎには注意ぐうたらし過ぎず適度な運動を、だってさ～", "", 0, 60002, 0, 4, 1, 0, 327, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　根を詰めずにリラックスすると運気向上！　ラッキーパーソンはアイドル。歌があなたを幸せにしてくれます♪", "", 0, 60002, 0, 4, 2, 0, 328, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("おみくじの結果はどうでしたか？\n新たに始まる一日が、あなたに\nとって良い日になりますように\nまた明日も遊びに来て下さいね♪", "カリン", 2, 60002, 190804, 0, 0, 0, 329, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("おみくじは楽しんで頂けましたか？\nあなたの新たなる年が\n素晴らしいものになるよう、\n心からお祈りいたします", "カリン", 3, 60002, 190804, 0, 0, 7, 330, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ささ、シェフィさまはこちらへ…", "コッコロ", 1, 80005, 105901, 0, 0, 1, 331, "", 4, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("コッコロさん、どこへ行くの…？\n…え？", "シェフィ", 1, 80005, 106401, 0, 0, 1, 332, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("『おめでとうございます！\nわ～パチパチー！』\n…という感じでどうですかね！？", "ペコリーヌ", 1, 80005, 105801, 0, 0, 1, 333, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ではわたくしも\n後ろからクラッカーを鳴らして\n応戦いたします\nああ、当日が待ち遠しいですね", "コッコロ", 2, 80005, 105901, 0, 0, 1, 334, "", 4, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ええと…\n二人とも何をしているの？", "シェフィ", 2, 80005, 106401, 0, 0, 1, 335, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("シェフィは初めてだもんね\nあの日が近いからって\n予行練習してんのよ\n気が早いわよね～", "キャル", 1, 80005, 106001, 0, 0, 1, 336, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あの日…？", "シェフィ", 3, 80005, 106401, 0, 0, 1, 337, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("その通りです…\nいよいよ記念すべきあの日が\n近づいてきましたよ！", "ペコリーヌ", 2, 80005, 105801, 0, 0, 1, 338, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("『プリンセスコネクト！\nRe:Dive』3.5周年！", "ペコリーヌ", 3, 80005, 105801, 0, 0, 1, 339, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("やばいですね☆", "カリン", 1, 80005, 190801, 0, 0, 1, 340, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("って、なにしれっと\n参加してんのよカリン！", "キャル", 2, 80005, 106001, 0, 0, 1, 341, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ふふ、いいじゃないですか\n【ギルド管理協会】として\n私もみなさんと一緒に\nお祝いをさせてください！", "カリン", 2, 80005, 190801, 0, 0, 1, 342, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("それに…記念日が近づけば\nとっておきの情報を\nお届けしますから♪", "カリン", 3, 80005, 190801, 0, 0, 1, 343, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("というわけで\n今日からシェフィちゃんも一緒に\nカウントダウンしちゃいましょう！\n3.5周年まで…", "ペコリーヌ", 4, 80005, 105801, 0, 0, 1, 344, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("えっ！？　ええとええと…！\nあ、あと14日…！", "シェフィ", 4, 80005, 106401, 0, 0, 1, 345, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("3.5周年まであと13日\n豪華に、そして盛大に\nお祝いしたいですね☆", "ペコリーヌ", 5, 80005, 105801, 0, 0, 2, 346, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("豪華といえば前にとある貴族さまが\n舞踏会を開かれたそうで\n主さまがそのお手伝いを\nしておりました", "コッコロ", 3, 80005, 105901, 0, 0, 2, 347, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("そこで美しい所作を学ばれたので\nわたくしも教えていただきました\nしゃなり、しゃなり…\nいかがでしょう？", "コッコロ", 4, 80005, 105901, 0, 0, 2, 348, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("すっごく上手ですよ☆\nまるでお姫様みたいです\nせっかくなのでわたしも\nしゃなりしゃなり", "ペコリーヌ", 6, 80005, 105801, 0, 0, 2, 349, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("さすがでございます\nペコリーヌさま", "コッコロ", 5, 80005, 105901, 0, 0, 2, 350, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("いや、あんたは\nできなきゃダメでしょ\n本物のお姫様なんだし", "キャル", 3, 80005, 106001, 0, 0, 2, 351, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("しゃなり、しゃなり…\nふふ、案外できるものね", "シェフィ", 5, 80005, 106401, 0, 0, 2, 352, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("わぁ！\nシェフィちゃん\n姿勢がとってもキレイです♪", "ペコリーヌ", 7, 80005, 105801, 0, 0, 2, 353, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("さ、次はキャルさまの\n番でございますよ", "コッコロ", 6, 80005, 105901, 0, 0, 2, 354, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あ、あたしはいいわよ！\nそういうの全然分かんないし…", "キャル", 4, 80005, 106001, 0, 0, 2, 355, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("大丈夫\nやってみると結構楽しいわよ\nほらほらっ", "シェフィ", 6, 80005, 106401, 0, 0, 2, 356, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("そ、そこまで言うなら…\nしゃなにゅわきゃあっ！", "キャル", 5, 80005, 106001, 0, 0, 2, 357, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("いたたた…もぉお～！\nなんであたしがこんな目に～！", "キャル", 6, 80005, 106001, 0, 0, 2, 358, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("まぁまぁ\n記念日までに練習すれば\nできるようになるかもしれません\nよろしければお教えいたしますよ", "コッコロ", 7, 80005, 105901, 0, 0, 2, 359, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("よし！\nあんたたちができて\nあたしだけできないのはしゃくだし\nやってやろうじゃないの！！", "キャル", 7, 80005, 106001, 0, 0, 2, 360, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("3.5周年まであと12日\n記念日当日はもちろんですが\nその日を待つ時間というのも\n心躍ります", "コッコロ", 8, 80005, 105901, 0, 0, 3, 361, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("分かりますっ！\nどんな特別な料理を食べられるのか\n考えるだけでワクワクしますよね！", "ペコリーヌ", 8, 80005, 105801, 0, 0, 3, 362, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("特別な料理といえば、お祭りですね\nそういえば主さまは学生として\n聖学祭に参加されたこと\nがあるとか…", "コッコロ", 9, 80005, 105901, 0, 0, 3, 363, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("聖学祭…って、なにかしら？", "シェフィ", 7, 80005, 106401, 0, 0, 3, 364, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("聖テレサ女学院の祭典ですよ\n二つのチームが競い合い\n青春を満喫するのが趣旨のようです", "コッコロ", 10, 80005, 105901, 0, 0, 3, 365, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("それってカルミナの\nサプライズライブがあった\nお祭りよね？\nちょっと見たかったかも…", "キャル", 8, 80005, 106001, 0, 0, 3, 366, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("カルミナの後の\nライブも好評だったらしいじゃない\n確か、なかよし部\nだったっけ…？", "キャル", 9, 80005, 106001, 0, 0, 3, 367, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("なかよし部…\n仲が良さそうな名前で\nやばいですね☆", "ペコリーヌ", 9, 80005, 105801, 0, 0, 3, 368, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("いや、そのまんますぎでしょ…", "キャル", 10, 80005, 106001, 0, 0, 3, 369, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("聖学祭かぁ…なんだか楽しそうね\nそれになかよし部の人たちも\n気になるわ", "シェフィ", 8, 80005, 106401, 0, 0, 3, 370, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("それじゃあわたしたちも、\n負けじと仲良くしましょう♪\nほらほらシェフィちゃん、\nぎゅーっ☆　ですよ♪", "ペコリーヌ", 10, 80005, 105801, 0, 0, 3, 371, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("えっ？　ええ…\nぎゅーっ…？", "シェフィ", 9, 80005, 106401, 0, 0, 3, 372, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("3.5周年まであと11日！？\nお祝いの準備進んでないんだけど…\nああ～昨日に戻りたいわ…", "キャル", 11, 80005, 106001, 0, 0, 4, 373, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("そういえばそんな魔道具があるって\n聞いたことがあるわね\n確か、名前はタイムラーベ…", "シェフィ", 10, 80005, 106401, 0, 0, 4, 374, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("なにそれヤバいわね\nでも本当にあるんだったら\n準備よりももっとやり直したいこと\nたくさんあるんだけど…", "キャル", 12, 80005, 106001, 0, 0, 4, 375, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("もしや正月の件でしょうか…？\nあの時はお金がなくて\n苦労しましたから", "コッコロ", 11, 80005, 105901, 0, 0, 4, 376, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あれはそうね…\nお金を湯水のように使う\nぺコリーヌを止められたら\nあんな苦労をすることもなかったし", "キャル", 13, 80005, 106001, 0, 0, 4, 377, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("そんなこともありましたね！\nやり直したいといえば\n『きゃるきゃる～ん♪』\nの方かと思いましたよ！", "ペコリーヌ", 11, 80005, 105801, 0, 0, 4, 378, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("バラすんじゃないわよ\nこのアホリーヌ！\nシェフィはそれ\n知らないんだから！", "キャル", 14, 80005, 106001, 0, 0, 4, 379, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("こうなったらもう、なんとか\nタイムラーべを探し出して\n今の会話をなかったことに…\nって、どうしたのよシェフィ", "キャル", 15, 80005, 106001, 0, 0, 4, 380, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("うん…もし、私だったら…\n私が知らないみんなとの時間を\n見てみたいな、って…", "シェフィ", 11, 80005, 106401, 0, 0, 4, 381, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("シェフィちゃん！　タイムなんとか\nなんかなくても大丈夫ですよ！\n一緒の時間はこれから\nどんどん作ればいいんですから！", "ペコリーヌ", 12, 80005, 105801, 0, 0, 4, 382, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("はい、今この瞬間も\n未来にはかけがえのない思い出に\nなっていることでしょう", "コッコロ", 12, 80005, 105901, 0, 0, 4, 383, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("だからそんな顔しないの\nほら、お祝いの準備、進めるわよ！", "キャル", 16, 80005, 106001, 0, 0, 4, 384, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("みんな…そうね\n最高のお祝いにして\n最高の思い出にしましょう！", "シェフィ", 12, 80005, 106401, 0, 0, 4, 385, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("3.5周年まで、あと10日！\nもうすぐですよー！\n楽しみすぎて、やばいですね！", "ペコリーヌ", 13, 80005, 105801, 0, 0, 5, 386, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("そういえば…たくさんのおもちゃが\n子どもたちを襲うっていう\n騒動もありましたね…\nなんでも勝手に動き出したとか！", "ペコリーヌ", 14, 80005, 105801, 0, 0, 5, 387, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("学校や孤児院とかに\nちっちゃなおもちゃが乗り込んで\n暴れたみたいですよ！", "ペコリーヌ", 15, 80005, 105801, 0, 0, 5, 388, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("暴れたって言っても\n所詮はおもちゃじゃない\nどうせちっさいんでしょ？", "キャル", 17, 80005, 106001, 0, 0, 5, 389, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("だったら魔法で\n全部ぶっ飛ばせばいいじゃない！\n大したことないわよ！", "キャル", 18, 80005, 106001, 0, 0, 5, 390, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("キャルってば…\n相手は子どもが\n大事にしてる物なのよ…？", "シェフィ", 13, 80005, 106401, 0, 0, 5, 391, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("乱暴な発言は\nめっ、でございますよ？\n子どもの教育に悪影響を\n与えてしまいますから…", "コッコロ", 13, 80005, 105901, 0, 0, 5, 392, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("キャルちゃんだって\n意外と猫グッズとか\nたっくさん集めてますよね？\nもしその子たちが暴れたら…？", "ペコリーヌ", 16, 80005, 105801, 0, 0, 5, 393, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("う、うっさいわね！\n意外とか言うな！\n…ま、まあ確かに正面切って\n魔法でぶっ飛ばせないかもね…", "キャル", 19, 80005, 106001, 0, 0, 5, 394, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あはは☆\nキャルちゃんのそういうところ\n好きですよ♪", "ペコリーヌ", 17, 80005, 105801, 0, 0, 5, 395, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("そんなキャルちゃんに猫グッズを\nプレゼントしちゃいますね！\n一部で流行っていた、たい焼き屋の\nおまけフィギュアですよ♪", "ペコリーヌ", 18, 80005, 105801, 0, 0, 5, 396, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("乱暴に扱ったりしないでくださいね\nひとりでに暴れ出しちゃうかも\nしれませんから！", "ペコリーヌ", 19, 80005, 105801, 0, 0, 5, 397, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("3.5周年まであと９日\nここでみなさんに\nビックニュースですよ！", "カリン", 4, 80005, 190801, 0, 0, 6, 398, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("3.5周年を祝う生放送に\n去年と同様【美食殿】の\nみなさんにご出演いただくことが\n決定しましたー！", "カリン", 5, 80005, 190801, 0, 0, 6, 399, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("…えっ！？", "キャル", 20, 80005, 106001, 0, 0, 6, 400, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("本当ですか！？\nそれじゃ今から張り切って\n生放送中に食べる魔物料理を\n作らなくちゃですね☆", "ペコリーヌ", 20, 80005, 105801, 0, 0, 6, 401, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("いや…がんばるところは\nそこじゃないような…\nというか去年も出演してたのね\nすごいじゃない！", "シェフィ", 14, 80005, 106401, 0, 0, 6, 402, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("はい。とても緊張しますが\nやりがいのある大役です\n一緒にがんばりましょうね\nシェフィさま", "コッコロ", 14, 80005, 105901, 0, 0, 6, 403, "", 4, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("わ、私も出るの！？　でも…\n私も【美食殿】の一人だものね\nそれなら今からしっかり準備をして\nコンディションを整えないと…", "シェフィ", 15, 80005, 106401, 0, 0, 6, 404, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ふふん♪\n生放送直前のカチコチになった\nシェフィの姿が楽しみだわ！", "キャル", 21, 80005, 106001, 0, 0, 6, 405, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("去年のキャルちゃんは\n緊張しすぎてずっと震えて\nかわいかったですもんね！\n今年もあの姿が見たいです！", "ペコリーヌ", 21, 80005, 105801, 0, 0, 6, 406, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ぶっ殺すぞ！？", "キャル", 22, 80005, 106001, 0, 0, 6, 407, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("というわけで\n『プリンセスコネクト！\nRe:Dive』の魅力を\nお伝えする生放送をお楽しみに♪", "カリン", 6, 80005, 190801, 0, 0, 6, 408, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("3.5周年まであと８日\nでございますよ\n楽しみですね、主さま", "コッコロ", 15, 80005, 105901, 0, 0, 7, 409, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("そういえばあんた\n夏休みの宿題は\nきちんとやってるの？", "キャル", 23, 80005, 106001, 0, 0, 7, 410, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("宿題…学校に通うのも\n楽しいことばかりじゃ\nないのね", "シェフィ", 16, 80005, 106401, 0, 0, 7, 411, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あれ？　そういえば\n少し前にルーセント学院で\n何かあったような…", "ペコリーヌ", 22, 80005, 105801, 0, 0, 7, 412, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ああ、始業式の日に\n大捕り物があったって\n話題になってたわね", "キャル", 24, 80005, 106001, 0, 0, 7, 413, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("夏休みを終わらせないって\n騒いでたっていう話？\nあれ本当なの？\n都市伝説だと思ってたわ", "シェフィ", 17, 80005, 106401, 0, 0, 7, 414, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("その一件ならよく存じ上げて\nおります。ですから主さま\n次の機会にはわたくしと一緒に\nがんばりましょう", "コッコロ", 16, 80005, 105901, 0, 0, 7, 415, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("楽しそう…私も一緒にやりたいな\nママ…じゃ、じゃなくて！\nコッコロさん、私もまざっていい？", "シェフィ", 18, 80005, 106401, 0, 0, 7, 416, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("もちろんでございます\n仲良くお勉強いたしましょう", "コッコロ", 17, 80005, 105901, 0, 0, 7, 417, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("しれっと教育ママが\n生まれてる…？", "キャル", 25, 80005, 106001, 0, 0, 7, 418, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("お勉強は大切ですよ！\nキャルちゃんも一緒に\nがんばりましょう！", "ペコリーヌ", 23, 80005, 105801, 0, 0, 7, 419, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("え～～～～！？", "キャル", 26, 80005, 106001, 0, 0, 7, 420, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("3.5周年まであと７日〜♪\nふふ～ん♪\nふんふふ～ん♪", "キャル", 27, 80005, 106001, 0, 0, 8, 421, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("…\nねぇコッコロさん\nキャル、どうしちゃったの？", "シェフィ", 19, 80005, 106401, 0, 0, 8, 422, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("とてもご機嫌そうに\n鼻歌を歌ってらっしゃいますね\n耳も尻尾もリズミカルに\n揺れて…ノリノリでございます", "コッコロ", 18, 80005, 105901, 0, 0, 8, 423, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あれはですね！\nカルミナのみなさんの\nサマーライブのチケットが\n手に入ったからなんですよ♪", "ペコリーヌ", 24, 80005, 105801, 0, 0, 8, 424, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ええっ！？\nあのライブのチケットって確か\n入手困難だったんじゃ…", "シェフィ", 20, 80005, 106401, 0, 0, 8, 425, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ふふふふ～ん♪\nしゃいにんぐふゅ～ちゃ～♪", "キャル", 28, 80005, 106001, 0, 0, 8, 426, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("なるほど…\nキャルさまがあのように\nなってしまうのも頷けますね", "コッコロ", 19, 80005, 105901, 0, 0, 8, 427, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("…カルミナの\n『Shining Future』\nの中に、シャイニングフューチャー\nって歌詞はなかったはずだけど…", "シェフィ", 21, 80005, 106401, 0, 0, 8, 428, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ふんふ…はっ！？\nあっ、あんたたち！\nなに人の鼻歌を\n勝手に聞いてるのよ！？", "キャル", 29, 80005, 106001, 0, 0, 8, 429, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("こっ、これは別に\nカルミナの曲じゃなくて…\nあたしのオリジナルソングよ！\n聞いたらお金取るわよっ！？", "キャル", 30, 80005, 106001, 0, 0, 8, 430, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("えへへ、キャルちゃん\nカルミナのサマーライブ\n思いっきり楽しみましょうね☆", "ペコリーヌ", 25, 80005, 105801, 0, 0, 8, 431, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("も～っ！\n生暖かい目で見るな～～！\nぶっ殺すわよ～～～！", "キャル", 31, 80005, 106001, 0, 0, 8, 432, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("3.5周年まであと６日\n３人も言ってたけど\nあっという間だったわね", "シェフィ", 22, 80005, 106401, 0, 0, 9, 433, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("…えっ？\n生放送の意気込み！？\n突然なに！？", "シェフィ", 23, 80005, 106401, 0, 0, 9, 434, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ええと…\nとにかく失敗しないように\n台本たくさん読んで…\nそれから…", "シェフィ", 24, 80005, 106401, 0, 0, 9, 435, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("えっ！？\nトラブルがあったら\nどうするのかって！？\nそ、それは…！", "シェフィ", 25, 80005, 106401, 0, 0, 9, 436, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("とにかく落ち着いて\nスタッフさんの指示を聞いて…", "シェフィ", 26, 80005, 106401, 0, 0, 9, 437, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("それから、それから…！\nぅ、ぅぅっ…！", "シェフィ", 27, 80005, 106401, 0, 0, 9, 438, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("―びえぇぇ～んっ！！！", "シェフィ", 28, 80005, 106401, 0, 0, 9, 439, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("どうされましたか、シェフィさま", "コッコロ", 20, 80005, 105901, 0, 0, 9, 440, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ううっ…ひっく…\nママッ…！", "シェフィ", 29, 80005, 106401, 0, 0, 9, 441, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("よしよし、緊張されてるのですね\nママが傍におりますよ\n主さま、少々お待ちくださいませ", "コッコロ", 21, 80005, 105901, 0, 0, 9, 442, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("…ふぅ\nシェフィさま\n生放送への意気込み\nお話しできそうですか？", "コッコロ", 22, 80005, 105901, 0, 0, 9, 443, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("…ううっ\n恥ずかしすぎて\nもう生放送出られない…", "シェフィ", 30, 80005, 106401, 0, 0, 9, 444, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("主さま\n3.5周年まであと５日\nでございます", "コッコロ", 23, 80005, 105901, 0, 0, 10, 445, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ですがその前に\n生放送がありますね", "コッコロ", 24, 80005, 105901, 0, 0, 10, 446, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("…生放送に向けた\n意気込みでございますか？", "コッコロ", 25, 80005, 105901, 0, 0, 10, 447, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("もちろんわたくしは\n主さまのために\n全身全霊を込めて\n楽しい時間をご提供いたします", "コッコロ", 26, 80005, 105901, 0, 0, 10, 448, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("…と、意気込んでみましたが\nうまくできるか少し不安です\n声が小さくなったり\n間違えてしまったらどうしようと…", "コッコロ", 27, 80005, 105901, 0, 0, 10, 449, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ですがわたくしは\n一人ではありません\n【美食殿】のみなさまが\nおります", "コッコロ", 28, 80005, 105901, 0, 0, 10, 450, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("どんな困難も\nみなさまと一緒なら\n乗り越えられると\nわたくし、確信しております", "コッコロ", 29, 80005, 105901, 0, 0, 10, 451, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("それに今回はシェフィさまも\nご参加されるわけですし\nママとしてお手本に\nならねばなりませんね", "コッコロ", 30, 80005, 105901, 0, 0, 10, 452, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("主さま。3.5周年も\n食卓を囲んでいる時のような\n楽しい思い出を\n一緒に作りましょうね", "コッコロ", 31, 80005, 105901, 0, 0, 10, 453, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("3.5周年まであと４日！\nやばいですね☆", "ペコリーヌ", 26, 80005, 105801, 0, 0, 11, 454, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("はいはい、やばいわね\nというかもうすぐ生放送だけど\nあんた準備はできてるの？", "キャル", 32, 80005, 106001, 0, 0, 11, 455, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ばっちりオイッスー☆　ですよ！\n『王家の装備』も全開です！", "ペコリーヌ", 27, 80005, 105801, 0, 0, 11, 456, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あとは前回を超える\n最高のオイッスー☆　を\nお届けできるように\n練習あるのみですかね！", "ペコリーヌ", 28, 80005, 105801, 0, 0, 11, 457, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("キャルちゃんは\nどうなんですか？\nオイッスー☆　を\n毎日ちゃんと練習してますか？", "ペコリーヌ", 29, 80005, 105801, 0, 0, 11, 458, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("はぁ！？　なんであたしまで\nその変なあいさつを練習しないと\nいけないのよ！", "キャル", 33, 80005, 106001, 0, 0, 11, 459, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("もしかしてやってないんですか？\nダメですよキャルちゃん！\nシェフィちゃんだってちゃんと\n毎日練習してるのに！", "ペコリーヌ", 30, 80005, 105801, 0, 0, 11, 460, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("こうなったらわたしがキャルちゃん\nにオイッスー☆　の『オ』から\nしっかり教えてあげないと！", "ペコリーヌ", 31, 80005, 105801, 0, 0, 11, 461, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("オイッスー☆　の『オ』は\n口を大きく開いて〜\nドラゴンの骨つき肉に\nかぶりつく直前をイメージして〜", "ペコリーヌ", 32, 80005, 105801, 0, 0, 11, 462, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("だからあたしはやるなんて一言も…", "キャル", 34, 80005, 106001, 0, 0, 11, 463, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("オイッスー☆", "ペコリーヌ", 33, 80005, 105801, 0, 0, 11, 464, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("聞きなさいっての！！", "キャル", 35, 80005, 106001, 0, 0, 11, 465, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("3.5周年まであと３日…\nそして生放送は、明日…", "シェフィ", 31, 80005, 106401, 0, 0, 12, 466, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("もっと台本を\n読み込んでおかないと…\nあと発声練習も…", "シェフィ", 32, 80005, 106401, 0, 0, 12, 467, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("おいっす！\n…こうじゃなかったわね\nええと確か…", "シェフィ", 33, 80005, 106401, 0, 0, 12, 468, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("うう…あんなに練習したのに\nこれじゃみんなに迷惑かけちゃう…", "シェフィ", 34, 80005, 106401, 0, 0, 12, 469, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("【美食殿】の一員として\n認められるように\n頑張らないといけないのに\nよし、もう一度…", "シェフィ", 35, 80005, 106401, 0, 0, 12, 470, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("やってますねシェフィちゃん！", "ペコリーヌ", 34, 80005, 105801, 0, 0, 12, 471, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("なによ、考えることは\nみんな同じってこと？", "キャル", 36, 80005, 106001, 0, 0, 12, 472, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ふふ。シェフィさま\nよろしければ\n仲間に入れてください\n一緒にやればきっとうまくできます", "コッコロ", 32, 80005, 105901, 0, 0, 12, 473, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("みんな…もちろんよ！", "シェフィ", 36, 80005, 106401, 0, 0, 12, 474, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("それじゃ明日の生放送に向けて\n一緒に練習がんばりましょう☆", "ペコリーヌ", 35, 80005, 105801, 0, 0, 12, 475, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("3.5周年まであと２日と\n迫った本日は…\nいよいよ生放送です！", "カリン", 7, 80005, 190801, 0, 0, 13, 476, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("【美食殿】のみなさんが\n準備に入られていますので\nそれぞれ繋いでみましょう！\nまずはペコリーヌさんです！", "カリン", 8, 80005, 190801, 0, 0, 13, 477, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日もオイッスー☆\nみんなで一緒に\nオイッスー☆", "ペコリーヌ", 36, 80005, 105801, 0, 0, 13, 478, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("お手本になるような\n発声練習ですね！\nそれでは続いてコッコロさん", "カリン", 9, 80005, 190801, 0, 0, 13, 479, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("はじめちょろちょろ\nなかぱっぱ～♪\n生放送前にみなさまで\n食卓を囲んで英気を養いましょう", "コッコロ", 33, 80005, 105901, 0, 0, 13, 480, "", 4, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("さすが【美食殿】のママですね！\nそしてキャルさんは…", "カリン", 10, 80005, 190801, 0, 0, 13, 481, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("大丈夫…大丈夫…\nあたしは大丈夫…", "キャル", 37, 80005, 106001, 0, 0, 13, 482, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("す、すごく震えてますけど\n大丈夫でしょうか…？\nそして今回初参加となる\n期待の新人シェフィさん！", "カリン", 11, 80005, 190801, 0, 0, 13, 483, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あうー？", "シェフィ", 37, 80005, 106401, 0, 0, 13, 484, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("あ…", "みんな", 37, 80005, 105801, 0, 0, 13, 485, "105901,34,106001,38,190801,12", 4, 1);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ちょ、ちょっとシェフィ！？\nなに赤ちゃん返りしてん―\nあ痛ぁっ！\n噛んだわこいつーっ！", "キャル", 39, 80005, 106001, 0, 0, 13, 486, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("シェフィさま\n緊張しすぎて\nしまったのでしょうね…\nおーよしよし…", "コッコロ", 35, 80005, 105901, 0, 0, 13, 487, "", 4, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("シェフィちゃん！\nそういう時は手のひらに\n好きな文字を書いて\n食べちゃうといいですよ！", "ペコリーヌ", 38, 80005, 105801, 0, 0, 13, 488, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("…ええと、現場からは以上です！\n生放送はもうすぐ！\n特別なお知らせもありますので\nどうぞお楽しみに！", "カリン", 13, 80005, 190801, 0, 0, 13, 489, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("3.5周年の記念日も\nいよいよ明日ね\n…って、あれ？", "シェフィ", 38, 80005, 106401, 0, 0, 14, 490, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("記念日はこの森へ行きませんか！？\nすっごく美味しいお肉が\nとれるんです☆", "ペコリーヌ", 39, 80005, 105801, 0, 0, 14, 491, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("うげ、またあの魔物？\nさすがに今度は\n丸焼きとかはやめてよね…\n見た目がヤバすぎるし", "キャル", 40, 80005, 106001, 0, 0, 14, 492, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ふふ、キャルさまもだいぶ\n魔物肉に慣れてきたようですね\n調理ならばわたくしに\nお任せください♪", "コッコロ", 36, 80005, 105901, 0, 0, 14, 493, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("みんな、何をしているの？\nなんだか、\n不穏な単語が聞こえたんだけど…", "シェフィ", 39, 80005, 106401, 0, 0, 14, 494, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("シェフィちゃん！\n明日の食べ尽くしツアーの\n相談をしてたんですよ！", "ペコリーヌ", 40, 80005, 105801, 0, 0, 14, 495, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("はい。明日は【美食殿】の\n一員となったシェフィさまと一緒に\n初めて記念日を過ごすのですから\n特別なコース料理を用意しませんと", "コッコロ", 37, 80005, 105901, 0, 0, 14, 496, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ふふん♪\n猫の毛も逆立つような\nあれこれを食べさせられるから\n覚悟しておいたほうがいいわよ？", "キャル", 41, 80005, 106001, 0, 0, 14, 497, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("へ、へぇ…", "シェフィ", 40, 80005, 106401, 0, 0, 14, 498, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("期待しててくださいね！\nシェフィちゃんとあなたに\n『おいちー！』って喜んでもらえる\n最高のごちそうを準備しますから☆", "ペコリーヌ", 41, 80005, 105801, 0, 0, 14, 499, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ええと…その…うーんと…\nわ、分かったわ\n私も【美食殿】の一員だもの", "シェフィ", 41, 80005, 106401, 0, 0, 14, 500, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("それにあなたも一緒みたいだし\n最後までがんばってみるわ…！", "シェフィ", 42, 80005, 106401, 0, 0, 14, 501, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("それではいつものあれを\nやりましょう！\n準備はいいですかっ？\n…いっきますよー！", "ペコリーヌ", 42, 80005, 105801, 0, 0, 15, 502, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("祝！", "キャル", 42, 80005, 106001, 0, 0, 15, 503, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("3.5周年！", "コッコロ", 38, 80005, 105901, 0, 0, 15, 504, "", 4, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("おめでとうございます！", "シェフィ", 43, 80005, 106401, 0, 0, 15, 505, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("この日を迎えられたのも\nあなたが『プリンセスコネクト！\nRe:Dive』を遊んでくれている\nおかげです！", "カリン", 14, 80005, 190801, 0, 0, 15, 506, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ということで\nみなさんからあなたへ一言ずつ\n感謝の言葉をどうぞ！", "カリン", 15, 80005, 190801, 0, 0, 15, 507, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("感謝の言葉ですか？　わたしは\n毎日あなたに感謝してますよ\n【美食殿】の仲間になってくれて…\n一緒にごはんを食べてくれて…", "ペコリーヌ", 43, 80005, 105801, 0, 0, 15, 508, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("なにより今でもわたしをぺコリーヌ\nって呼んでくれてありがとうござい\nます。これからもわたしはあなたの\nぺコリーヌです！　やばいですね☆", "ペコリーヌ", 44, 80005, 105801, 0, 0, 15, 509, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("えっ！？　今度はあたし！？\n感謝って…まぁ、そうね…\nあんたにはあたしが\n辛くて苦しい時に助けてもらって…", "キャル", 43, 80005, 106001, 0, 0, 15, 510, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("でもおかげで色々吹っ切れたわ！\nもしあんたが困ってたら今度は\nあたしが助けてあげるから\nその時はちゃんと言いなさいよ！", "キャル", 44, 80005, 106001, 0, 0, 15, 511, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ええと…次は私ね\n実はよく覚えてないのだけど\n空から落ちてきた私を受け止めて\nくれたのはあなたなのでしょう？", "シェフィ", 44, 80005, 106401, 0, 0, 15, 512, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("最初に私を見つけてくれたのが\nあなたで良かったって思ってるの\nおかげで私は居場所を見つけたから\nあなたがくれたもの、大切にするわ", "シェフィ", 45, 80005, 106401, 0, 0, 15, 513, "", 0, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("では最後にわたくしから…\nわたくしは主さまの元を離れた日…\nこのように記念日をお祝いする\nことは二度とないと思っていました", "コッコロ", 39, 80005, 105901, 0, 0, 15, 514, "", 4, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("ですが、主さまはわたくしを\n迎えにきてくださり、今もこうして\nおそばにおいてくださっています\nわたくしにとって毎日が記念日です", "コッコロ", 40, 80005, 105901, 0, 0, 15, 515, "", 4, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("わたくしたちの物語は\nまだ続いていきます\nこれからも一緒にページを\n作っていきましょうね", "コッコロ", 41, 80005, 105901, 0, 0, 15, 516, "", 4, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("それじゃ\nいつものあれでしめますよ！\nみんなで一緒に、さんはい☆", "ペコリーヌ", 45, 80005, 105801, 0, 0, 15, 517, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("これからも\nよろしくおねがいします！", "みんな", 46, 80005, 105801, 0, 0, 15, 518, "105901,42,106001,45,106401,46,190801,16", 4, 1);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("新年を迎え、新たに始まる一日を\nおみくじで占ってみませんか？\n良い運勢であるほど、\n沢山のプレゼントが貰えますよ♪", "カリン", 1, 60003, 190804, 0, 1, 0, 519, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　どんな不可能も可能にできちゃう！　　　　仲間と食卓を囲めばさらに運気上昇よ！　ただし魔物料理以外！", "", 0, 60003, 0, 1, 1, 0, 520, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　やること全てが最高潮！　やばいですね☆　ラッキーアイテムはおにぎり！　お腹一杯で幸せが続くでしょう！", "", 0, 60003, 0, 1, 1, 0, 521, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　羽が生えたように飛躍できる絶好調の運気！新しいことに挑戦するなら今しかないわ！　やってみましょう！", "", 0, 60003, 0, 1, 1, 0, 522, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　精霊も新年の幸福をお祝いしています！　　主さまの笑顔が見られて、わたくしも幸せいっぱいでございます♪", "", 0, 60003, 0, 1, 1, 0, 523, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　やること全てが上手くいく最高の一日！　　あなたの活躍に先生もにっこりです。いい子いい子♪", "", 0, 60003, 0, 1, 2, 0, 524, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　お裁縫好きな女の子のお墨付きです！　　　お世話したがりの妹にめいっぱい愛されちゃうかも！？", "", 0, 60003, 0, 2, 1, 0, 525, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　ラッキーカラーは赤！　　　　　　　　　　湧き上がるアイデアの数々に、高笑いが止まりませんわ！", "", 0, 60003, 0, 2, 1, 0, 526, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　ラッキーカラーは鮮やかな黄色！　　　　　さらにシマシマのアイテムを持つと、運気倍増らしいッスよ♪", "", 0, 60003, 0, 2, 1, 0, 527, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　秘められた力が開花するでしょう！　　　　じゃあ、私の龍眼と力比べしてみようか？　ふふ、冗談だよ～", "", 0, 60003, 0, 2, 1, 0, 528, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　悩んでいたことが解決しそうです！　　　　たまには勉強も仕事も忘れて、心あたたまる家族と過ごしましょ！", "", 0, 60003, 0, 2, 2, 0, 529, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　家の中でゆっくり過ごすのがよさそう！　　ラッキーアイテムはゲームよ！　ベストスコアを更新できるかも？", "", 0, 60003, 0, 3, 1, 0, 530, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　上手くなりたいことに積極的に挑戦してみてサックス好きの妹が、手取り足取りサポートしてくれるかも～？", "", 0, 60003, 0, 3, 1, 0, 531, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　仕事運が急上昇中です！　　　　　　　　　きっと「煉獄に舞う一陣の疾風」の如き活躍ができますよ！", "", 0, 60003, 0, 3, 1, 0, 532, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　日頃の努力が報われます！　　　　　　　　親しい友人がいるなら報告してみて。一緒に喜んでくれるはずだ。", "", 0, 60003, 0, 3, 1, 0, 533, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　ラッキーアイテムはかわいいもの！　　　　ア、アタシはかわいいじゃなくてキレイだってば！　も～っ！", "", 0, 60003, 0, 3, 1, 0, 534, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　チャンスを待つと良い結果に！　　　　　　ラッキーアイテムのプリンを食べて、運を呼び込みましょう！", "", 0, 60003, 0, 3, 1, 0, 535, "", 2, 0);
