INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("おみくじの結果はどうでしたか？\n新たに始まる一日が、あなたに\nとって良い日になりますように\nまた明日も遊びに来て下さいね♪", "カリン", 2, 60003, 190804, 0, 0, 0, 544, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("おみくじは楽しんで頂けましたか？\nあなたの新たなる年が\n素晴らしいものになるよう、\n心からお祈りいたします", "カリン", 3, 60003, 190804, 0, 0, 7, 545, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("新年を迎え、新たに始まる一日を\nおみくじで占ってみませんか？\n良い運勢であるほど、\n沢山のプレゼントが貰えますよ♪", "カリン", 1, 60004, 190804, 0, 1, 0, 546, "", 1, 0);
