INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　外に出てゆっくり過ごすと運気が上昇！　　ラッキースポットは牧場。面白い出会いがありそうです♪", "", 0, 60005, 0, 4, 1, 0, 593, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　いろんな事件が起こる一日になりそう！　　状況をよく観察してみようじゃないか！　まさに探偵のごとくね！", "", 0, 60005, 0, 4, 1, 0, 594, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　難しい頼み事をされるかもしれません！　　うまくやれればきっと成長につながります、挑戦してみましょう！", "", 0, 60005, 0, 4, 1, 0, 595, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　空を眺めると気持ちが晴れやかに！　　　　眺めるだけじゃなくて、ひとっ飛びしちゃいましょうかっ♪", "", 0, 60005, 0, 4, 2, 0, 596, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　掃除をすると運勢が開けそう！　　　　　　「わ、めんど」「ヴルムっ！　新年早々サボっちゃダメなんだからね！」", "", 0, 60005, 0, 4, 2, 0, 597, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("おみくじの結果はどうでしたか？\n新たに始まる一日が、あなたに\nとって良い日になりますように\nまた明日も遊びに来て下さいね♪", "カリン", 2, 60005, 190804, 0, 0, 0, 598, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("おみくじは楽しんで頂けましたか？\nあなたの新たなる年が\n素晴らしいものになるよう、\n心からお祈りいたします", "カリン", 3, 60005, 190804, 0, 0, 7, 599, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("新年を迎え、新たに始まる一日を\nおみくじで占ってみませんか？\n良い運勢であるほど、\n沢山のプレゼントが貰えますよ♪", "カリン", 1, 60006, 190804, 0, 1, 0, 600, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　勇気を持って、新しいことに挑戦しよう！\n幸先がいいねえ少年！　今年もいい一年になるよう祈ってるよ。", "", 0, 60006, 0, 1, 2, 0, 601, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　どんなピンチも簡単に乗り越えられそう！\nよい結果が出たようで何よりです。さて、待人の方は……ふふ。", "", 0, 60006, 0, 1, 2, 0, 602, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　あの人と仲直り……できちゃうかも！？\nはあ……この私があなたの運勢に興味を抱くわけないでしょう？", "", 0, 60006, 0, 1, 2, 0, 603, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　身近な友達との絆が深まる予感……？\n騎士様は、どなたと友誼を結ぶのでしょう？　気になります……", "", 0, 60006, 0, 2, 1, 0, 604, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　ラッキーアイテムは「蛇の抜け殻」！\nこのアタシにお目にかかれるなんて……アンタ、幸せものね♪", "", 0, 60006, 0, 2, 2, 0, 605, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　気になるあの人に会えちゃうかも！？\n『初夢を正夢にする枕』であなたに会え……な、なんでもない！", "", 0, 60006, 0, 3, 2, 0, 606, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　子供に戻って、一日中遊びつくそう！\nお年玉でけん玉ゲット！　おじちゃん、もしかめ一万回やって！", "", 0, 60006, 0, 3, 2, 0, 607, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　今日はおうちで、ゆーっくりくつろごう。\nお雑煮よし。みかんよし。さ、こたつで寝正月だ。君も入る？", "", 0, 60006, 0, 3, 1, 0, 608, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　突然のドッキリに注意！\nおや、後ろに髪の長い女の霊が──フフ、冗談です。私ですよ。", "", 0, 60006, 0, 4, 2, 0, 609, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉。慌てなくても、幸運はきっとやってくる。\n運は自分で掴むもの──媛が言ってました。でも、どうやって？", "", 0, 60006, 0, 4, 2, 0, 610, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("おみくじの結果はどうでしたか？\n新たに始まる一日が、あなたに\nとって良い日になりますように\nまた明日も遊びに来て下さいね♪", "カリン", 2, 60006, 190804, 0, 0, 0, 611, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("おみくじは楽しんで頂けましたか？\nあなたの新たなる年が\n素晴らしいものになるよう、\n心からお祈りいたします", "カリン", 3, 60006, 190804, 0, 0, 5, 612, "", 3, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("新年を迎え、新たに始まる一日を\nおみくじで占ってみませんか？\n良い運勢であるほど、\n沢山のプレゼントが貰えますよ♪", "カリン", 1, 60007, 190804, 0, 1, 0, 613, "", 1, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　絶好調で最高の一日になりそう♪\nわたしも、騎士クンが一緒ならいつだって最高に幸せな日だよ……", "", 0, 60007, 0, 1, 2, 0, 614, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　新しいことに挑戦するチャンス！\nお姉さんも一緒に挑戦しちゃおっかな♪　飲み処の新規開拓とか！", "", 0, 60007, 0, 1, 2, 0, 615, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は姫吉！　日々の努力が実を結ぶ予感！\n今日一日鍛錬に勤しむべき、ということだな。では早速行こうか。", "", 0, 60007, 0, 1, 2, 0, 616, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　家族サービスにはぴったりの日！\nさっそく弟くんにあまあまお姉ちゃんの出血大サービス、だよっ♪", "", 0, 60007, 0, 2, 2, 0, 617, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は大吉！　笑顔で過ごせば周りもみんなハッピーかも！\n『笑う顔はフグになる』ですねっ。幸せいっぱいお届けしますっ", "", 0, 60007, 0, 2, 2, 0, 618, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　恋愛運良し、積極的な行動に成果が！？\nじゃあ騎士さんのこと、拉致しちゃうとか★　恋愛成就確定です♥", "", 0, 60007, 0, 3, 2, 0, 619, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は中吉！　おめかししたら運気も上昇？\n毛並がふわふわになるまでブラッシングしたわ♪　ふふ、完璧ね！", "", 0, 60007, 0, 3, 2, 0, 620, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　知らない場所に行くと新たな発見が！\n未知の場所……一人では恐ろしくて。騎士さま、どうかお力添えを", "", 0, 60007, 0, 4, 2, 0, 621, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("今日の運勢は小吉！　ラッキーアイテムは鳥の羽根！\nだからって、私の羽を毟ろうとしないでくださ～いっ！", "", 0, 60007, 0, 4, 2, 0, 622, "", 2, 0);
INSERT INTO `v1_e564c4467544c6679c0c13788b9fbcd7b199a7e6a846de599a40531e34b76cae` VALUES ("おみくじの結果はどうでしたか？\n新たに始まる一日が、あなたに\nとって良い日になりますように\nまた明日も遊びに来て下さいね♪", "カリン", 2, 60007, 190804, 0, 0, 0, 623, "", 3, 0);
